struct Trait {
    static constexpr bool value = false;
};

// Specialization for integral types
template <typename T>
struct Trait<T, typename std::enable_if<std::is_integral<T>::value>::type> {
    static constexpr bool value = true;
};

// Function enabled only if T is integral
template <typename T>
auto process(T t) -> typename std::enable_if<Trait<T>::value, void>::type {
    // Implementation for integral types
}

// Function disabled if T is not integral
template <typename T>
auto process(T t) -> typename std::enable_if<!Trait<T>::value, void>::type {
    // Implementation for non-integral types
}

